package calc

func primes(n int64) int64 {
	var count int64
	for k := int64(2); k < n; k++ {
		isP := true
		for d := int64(2); d*d <= k; d++ {
			if k%d == 0 {
				isP = false
				break
			}
		}
		if isP {
			count++
		}
	}
	return count
}

package calc

import "testing"

func TestPrimes(t *testing.T) {
	if got := primes(10); got != 4 {
		t.Errorf("primes(10) = %d, want 4", got)
	}
	if got := primes(100); got != 25 {
		t.Errorf("primes(100) = %d, want 25", got)
	}
}
